INSERT INTO `templates` (`id`, `title`, `description`, `sections`, `is_active`, `created_by`, `created_by_name`, `created_at`, `updated_at`, `standard_key`) VALUES ('52931771-e262-4b62-9704-94545b2185e3','Audit industriel — Usine S2I','Trame standard pour les audits usine : ventes, ordres de fabrication, machines/moules, matières premières, rebuts, recouvrement, RH et sécurité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"ebbb0a6e-db2c-47c5-9891-4c922a28c41e\",\"label\":\"Ventes et chiffre d\'affaires\",\"questions\":[{\"id\":\"7a8affa4-385c-4dd7-b2c7-228b77aad72c\",\"text\":\"L\'évolution du chiffre d\'affaires du mois est-elle conforme aux objectifs ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"66160ca0-d4b3-4888-8a2e-19b8058ef735\",\"text\":\"Précisez les écarts constatés et leurs causes (perte de clients, nouveaux clients…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"7a8affa4-385c-4dd7-b2c7-228b77aad72c\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"ed8f451a-5eae-4966-a633-2a13937ced3b\",\"text\":\"Des clients majeurs ont-ils réduit ou arrêté leurs commandes ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"0040726e-a6aa-410f-96d6-97a182b441f1\",\"text\":\"Précisez les clients concernés et le plan d\'action commercial\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"ed8f451a-5eae-4966-a633-2a13937ced3b\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"c2e18930-d6c8-45a8-85f7-85d9cdaccc4f\",\"label\":\"Ordres de fabrication et sorties matière\",\"questions\":[{\"id\":\"a0c268c7-111e-4b0c-bfed-531027af02eb\",\"text\":\"Les ordres de fabrication et bons de sortie matière première sont-ils tous enregistrés et cohérents ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"0adf7d0d-89e9-4d39-8bec-3b614ee079c0\",\"text\":\"Précisez les écarts ou retards de saisie constatés et la cause (absence, surcharge…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a0c268c7-111e-4b0c-bfed-531027af02eb\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"20e9c66d-7d25-4ee7-a2ae-424b7b21a003\",\"label\":\"État des machines et moules\",\"questions\":[{\"id\":\"b5fce843-768f-4adc-90bf-889c9ce439ff\",\"text\":\"Les machines et moules sont-ils en bon état de fonctionnement ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"a40723bc-8a3f-42d2-8bb7-a32984457747\",\"text\":\"Détail des pannes constatées (machine, pièce, durée) et plan d\'action\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"b5fce843-768f-4adc-90bf-889c9ce439ff\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"73844168-3e4d-469d-82d2-947709f7e7fb\",\"text\":\"Nombre de machines à l\'arrêt lors de la visite\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false}]},{\"id\":\"90d5fcfa-9813-4d02-9068-d22ad753516e\",\"label\":\"Inventaire matières premières\",\"questions\":[{\"id\":\"bedd8740-fe32-4ba3-8f47-f593e8498b34\",\"text\":\"Le stock physique de matières premières correspond-il aux données système ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"34468e92-5904-4569-9ca6-fef413b4cbb2\",\"text\":\"Précisez les articles et quantités en écart\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"bedd8740-fe32-4ba3-8f47-f593e8498b34\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"1dc03111-c0ff-4979-bf7f-a341b8585c38\",\"label\":\"Rebuts et déchets\",\"questions\":[{\"id\":\"26c4b2c4-3ae7-43d8-bb65-862db203cdcd\",\"text\":\"Le taux de rebuts constaté est-il dans la norme attendue ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"5b816a30-5c7e-4716-80a8-7bf65b95c73b\",\"text\":\"Taux de rebuts constaté (%)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"26c4b2c4-3ae7-43d8-bb65-862db203cdcd\",\"triggerValues\":[\"no\"]}},{\"id\":\"dfa6e6fb-5aba-4a6c-a862-019ee06159f1\",\"text\":\"Le stock de déchets à vendre est-il suivi et écoulé régulièrement ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]},{\"id\":\"46ccb7d3-92c9-4e38-9e85-3f365058a06e\",\"label\":\"Suivi balance client et recouvrement\",\"questions\":[{\"id\":\"4e048819-b492-4775-a1a4-531e1e8eebab\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"94e34cb9-4504-47a3-aea6-c9e6840a4d0d\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"176cf788-729c-42c8-912c-d5860d9319d6\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"4e048819-b492-4775-a1a4-531e1e8eebab\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"9fc243e7-53d3-477d-bd65-fc37fcd75ab6\",\"label\":\"Organisation et climat social\",\"questions\":[{\"id\":\"1dccd9a8-64ec-4f3b-8cd4-51113ca22d98\",\"text\":\"Les effectifs (production, administratif) sont-ils suffisants ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"6e1772ea-9a5f-4b07-965c-5e1395f61eeb\",\"text\":\"Précisez les postes en tension et les recommandations\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"1dccd9a8-64ec-4f3b-8cd4-51113ca22d98\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"ac13eda0-abd1-45c9-8d3d-3329b3700036\",\"text\":\"Un conflit ou climat social tendu a-t-il été observé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"468cf264-7a14-472b-89f6-aecc7513c787\",\"text\":\"Détail du conflit constaté et mesures recommandées\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"ac13eda0-abd1-45c9-8d3d-3329b3700036\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"01ef687c-4b67-4c21-8395-ef594f964489\",\"label\":\"Hygiène, sécurité et environnement usine\",\"questions\":[{\"id\":\"95cb80ea-f64f-47a4-8866-2c1531b6ef2a\",\"text\":\"L\'état de propreté de l\'usine est-il satisfaisant ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true},{\"id\":\"bd237a4d-4eca-481c-b7ad-fb65de13c2b3\",\"text\":\"Les équipements de sécurité (extincteurs, caméras) sont-ils opérationnels et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"9e4f7119-562e-47fe-acde-5970f28cd602\",\"text\":\"Précisez les anomalies constatées et les actions correctives\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"bd237a4d-4eca-481c-b7ad-fb65de13c2b3\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"997a0c69-8181-4422-8318-b1a90e207584\",\"text\":\"Le matériel informatique (postes, imprimantes) est-il suffisant et fonctionnel ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T09:37:46.385Z','2026-10-21T09:37:46.385Z','usine'),
('6529f664-a252-410e-b97c-c95ae65d587c','Audit logistique et commercial — Dépôt','Trame standard pour les audits dépôt : inventaire stock, clôture de caisse, facturation/livraison, retours clients, organisation et recouvrement. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"d4f6ae0b-7999-4b1b-b978-9da8dd6df490\",\"label\":\"Inventaire stock dépôt\",\"questions\":[{\"id\":\"386d60bd-e2d3-4a20-bf21-2c9fa8597fda\",\"text\":\"Le stock physique correspond-il au stock système (PROXIM/PROMOFOOD/BEESKY) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"1a51cd71-6c09-41d0-b729-75ad4d36b5ab\",\"text\":\"Précisez la nature et la valeur de l\'écart constaté (article, quantité, montant)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"386d60bd-e2d3-4a20-bf21-2c9fa8597fda\",\"triggerValues\":[\"no\"]}},{\"id\":\"e7d4ecc5-dc2e-4432-8b6e-7f678a5e0e6d\",\"text\":\"Des articles endommagés ou périmés ont-ils été identifiés ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"84fcb066-fe3f-4da2-97f2-526d72c3946a\",\"text\":\"Détail des articles concernés et prix de liquidation proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"e7d4ecc5-dc2e-4432-8b6e-7f678a5e0e6d\",\"triggerValues\":[\"yes\"]}},{\"id\":\"6534184a-cb70-40e8-98a9-359f638b83f2\",\"text\":\"Les mouvements de stock (transferts entre dépôts, gestes commerciaux) sont-ils tracés formellement ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"7a4378f7-5fd8-4307-8000-d285c48ade24\",\"text\":\"Précisez les manques de traçabilité constatés\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"6534184a-cb70-40e8-98a9-359f638b83f2\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"27dc2624-235b-442c-8a9b-7972597816cb\",\"label\":\"Clôture de caisse et inventaire véhicule (agents commerciaux)\",\"questions\":[{\"id\":\"7800a42e-5713-4c2a-9212-a896dfeaa943\",\"text\":\"Un écart a-t-il été constaté entre le système (NOMADIS) et les espèces encaissées ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"30c13997-a3ca-43c7-8ad2-c405fa7b7222\",\"text\":\"Montant de l\'écart constaté (DT)\",\"type\":\"NUMBER\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"7800a42e-5713-4c2a-9212-a896dfeaa943\",\"triggerValues\":[\"yes\"]}},{\"id\":\"deab57d8-e8d2-426b-8805-a8fd34aaa54a\",\"text\":\"Un justificatif a-t-il été présenté par l\'agent ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"7800a42e-5713-4c2a-9212-a896dfeaa943\",\"triggerValues\":[\"yes\"]}},{\"id\":\"be00ced7-638d-4004-a5ca-5f612b4257c1\",\"text\":\"L\'écart a-t-il été régularisé immédiatement ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"7800a42e-5713-4c2a-9212-a896dfeaa943\",\"triggerValues\":[\"yes\"]}},{\"id\":\"3dbb5e25-5ce8-4a29-93aa-e844c70e1bec\",\"text\":\"Un écart a-t-il été constaté lors de l\'inventaire du stock véhicule ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"3ad6a9e4-f347-4d9b-ba27-5509a5b8a374\",\"text\":\"Montant/quantité de l\'écart et régularisation effectuée\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"3dbb5e25-5ce8-4a29-93aa-e844c70e1bec\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"c0b1406a-e25e-4dca-ad08-1a2751a54890\",\"label\":\"Facturation, livraison et retours clients\",\"questions\":[{\"id\":\"1574fb43-9558-4ae5-9505-5fad13caf26e\",\"text\":\"Les livraisons sont-elles systématiquement facturées avant sortie de marchandise ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"4f9bf970-043c-4824-876a-78a677eff240\",\"text\":\"Précisez les cas de livraison sans facturation préalable et la régularisation effectuée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"1574fb43-9558-4ae5-9505-5fad13caf26e\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"4116052d-d075-4b96-b880-bbcef4d638bb\",\"text\":\"Les remises accordées sont-elles validées officiellement avant application ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"a29071fc-055e-40db-a219-6cea2a358f2b\",\"text\":\"Les retours clients sont-ils traités selon la procédure (déclaration, validation direction) ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"a487ed3a-0bf1-4fe8-8d64-ab8798f2e6a2\",\"text\":\"Précisez les retours en attente et l\'origine du blocage\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"a29071fc-055e-40db-a219-6cea2a358f2b\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"e61115e4-f75d-4702-b6ae-224fd31123f0\",\"label\":\"Organisation et ressources humaines\",\"questions\":[{\"id\":\"2232b378-813a-4597-a169-699b7fdbef17\",\"text\":\"Les effectifs administratifs sont-ils suffisants pour les tâches du dépôt ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"f378aa86-934f-4d6d-966c-3de524691110\",\"text\":\"Précisez les tâches impactées et les recommandations (recrutement, réorganisation…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"2232b378-813a-4597-a169-699b7fdbef17\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"6ec7ad78-112b-4e7e-aab3-c001923ae791\",\"text\":\"Un organigramme clair et une répartition des tâches sont-ils en place ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true}]},{\"id\":\"9fca6aa2-aaef-4770-8c22-0c98e9ca5be6\",\"label\":\"Suivi balance client, recouvrement et effets\",\"questions\":[{\"id\":\"c95a12ac-d72f-4ce9-a441-909837d00e07\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"8e32abef-fde9-4746-b388-4e99ba56aa52\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"c3dfcb36-8e3b-4fc1-935a-5249203cc2a5\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"c95a12ac-d72f-4ce9-a441-909837d00e07\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"e4f68ddb-25f9-4992-93af-d18e121afd11\",\"text\":\"La gestion des effets (traites, échéances) est-elle rigoureuse et à jour ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T09:37:46.388Z','2026-10-21T09:37:46.388Z','depot'),
('abec3708-4324-4091-b32b-01e24219ffe0','Audit logistique — Déchargement de containers importés','Grille de contrôle standard pour le déchargement des containers importés : contrôle documentaire avant ouverture, inspection de l\'état général, comptage contradictoire et DLC, procédure en cas de non-conformité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"270092d0-02a6-450b-a1dd-dbfea43fddd4\",\"label\":\"Contrôle documentaire (avant ouverture)\",\"questions\":[{\"id\":\"84962244-d8ba-4d5e-860a-32a8086f1cba\",\"text\":\"Le Bill of Lading est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"62fd2fbf-77f3-4ea3-9252-515ad2d2ee41\",\"text\":\"Précisez l\'anomalie constatée sur le Bill of Lading\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"84962244-d8ba-4d5e-860a-32a8086f1cba\",\"triggerValues\":[\"no\"]}},{\"id\":\"b1066d33-27e4-4746-9899-2852bac476e7\",\"text\":\"Le certificat sanitaire est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"705fe51f-8a62-4876-a227-1e7b763aab71\",\"text\":\"Précisez l\'anomalie constatée sur le certificat sanitaire\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"b1066d33-27e4-4746-9899-2852bac476e7\",\"triggerValues\":[\"no\"]}},{\"id\":\"e73c87e4-d0b4-4911-894f-d4bc3d8c405f\",\"text\":\"Le certificat d\'origine est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"a5503b4b-8913-4a44-b4ea-7859821c866a\",\"text\":\"Précisez l\'anomalie constatée sur le certificat d\'origine\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"e73c87e4-d0b4-4911-894f-d4bc3d8c405f\",\"triggerValues\":[\"no\"]}},{\"id\":\"7bb04f08-09ff-43e0-b21e-05ef9b2becd4\",\"text\":\"Le Packing List est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"9cd18e3a-b112-48d6-a5a4-9b9f34cb169c\",\"text\":\"Précisez l\'anomalie constatée sur le Packing List\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"7bb04f08-09ff-43e0-b21e-05ef9b2becd4\",\"triggerValues\":[\"no\"]}},{\"id\":\"0a677442-3e1d-4b87-a5be-2eb7f2f54597\",\"text\":\"Autres documents contrôlés (facture, etc.) — précisez lesquels et leur conformité\",\"type\":\"TEXT\",\"weight\":1,\"required\":false},{\"id\":\"fc8cd83c-78bd-402a-a3cd-4a9dbb6d454a\",\"text\":\"Existe-t-il un plombage identifiable et numéroté ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"c2d924b1-7deb-4157-95d6-cccbd169cb92\",\"text\":\"Précisez l\'anomalie constatée (absence de plombage, numéro illisible…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"fc8cd83c-78bd-402a-a3cd-4a9dbb6d454a\",\"triggerValues\":[\"no\"]}},{\"id\":\"6cf01dd9-ba4b-46f1-b884-4975abc80a18\",\"text\":\"Numéro du plombage relevé\",\"type\":\"TEXT\",\"weight\":1,\"required\":false}]},{\"id\":\"83e2a161-60ac-4a13-b2a1-6ba190a53775\",\"label\":\"Inspection de l\'état général du container\",\"questions\":[{\"id\":\"c67d15cd-16ca-4112-906c-fa13bda3165d\",\"text\":\"Le container est-il intact (absence d\'ouvertures ou de fuites) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"a3947483-62a8-40ce-8b62-3a0fc0f54b6e\",\"text\":\"Précisez l\'ouverture ou la fuite constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"c67d15cd-16ca-4112-906c-fa13bda3165d\",\"triggerValues\":[\"no\"]}},{\"id\":\"53e8b1e0-27a4-47eb-939e-b148775db4fa\",\"text\":\"L\'ouverture des portes du container ne révèle-t-elle aucune anomalie ou suspicion ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"abcc0918-d98f-4ef1-a48b-c946b8d2aa37\",\"text\":\"Précisez l\'anomalie ou la suspicion constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"53e8b1e0-27a4-47eb-939e-b148775db4fa\",\"triggerValues\":[\"no\"]}},{\"id\":\"c4f0ac36-c121-44eb-a5bf-df50f0c55603\",\"text\":\"Le contrôle visuel initial confirme-t-il qu\'aucun carton ou sac n\'est ouvert ou endommagé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"d1474c33-5c78-48ed-9405-3776e3c7e1c7\",\"text\":\"Précisez les cartons/sacs ouverts ou endommagés constatés\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"c4f0ac36-c121-44eb-a5bf-df50f0c55603\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"12c9e6ba-8311-4a1f-8090-87a3ecce88ed\",\"label\":\"Opérations de déchargement et traçabilité\",\"questions\":[{\"id\":\"1f42ee35-594b-47d0-b2cc-e0d55b7305b1\",\"text\":\"Le comptage contradictoire correspond-il au Packing List (et aux autres documents : facture, Bill of Lading) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"639fc57d-1b89-4ff6-81b1-f02c000b3143\",\"text\":\"Précisez l\'écart constaté (référence, quantité)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"1f42ee35-594b-47d0-b2cc-e0d55b7305b1\",\"triggerValues\":[\"no\"]}},{\"id\":\"1d65fb31-c892-4afe-b500-b23c452f891f\",\"text\":\"Écart de quantité constaté (unités)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false,\"dependsOn\":{\"questionId\":\"1f42ee35-594b-47d0-b2cc-e0d55b7305b1\",\"triggerValues\":[\"no\"]}},{\"id\":\"ef25280a-a0b0-4522-8aed-797c55cdff2d\",\"text\":\"Le contrôle des DLC par échantillonnage est-il conforme ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"768abda0-8e7b-460d-8963-163eafef62a7\",\"text\":\"Précisez les références et DLC non conformes constatées\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"ef25280a-a0b0-4522-8aed-797c55cdff2d\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"8765aca8-3ead-48a4-9cc6-95e1ec6e55be\",\"label\":\"Procédure en cas de non-conformité\",\"questions\":[{\"id\":\"d0171833-dcde-4909-9bee-7e98be5214b9\",\"text\":\"Une non-conformité a-t-elle été détectée durant cet audit ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"951d19f3-0753-4661-bacc-df05710bc712\",\"text\":\"Description de la non-conformité constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"d0171833-dcde-4909-9bee-7e98be5214b9\",\"triggerValues\":[\"yes\"]}},{\"id\":\"1ebaa8fa-ea32-4b60-88cf-c8bd8fa0f21e\",\"text\":\"Des photographies horodatées ont-elles été prises (scellé cassé, marchandise endommagée, container peu rempli…) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"d0171833-dcde-4909-9bee-7e98be5214b9\",\"triggerValues\":[\"yes\"]}},{\"id\":\"9edfcd28-6b5f-46ed-bc23-5b814abddbaf\",\"text\":\"Le lot a-t-il été bloqué en zone de quarantaine (non-conformité majeure) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"d0171833-dcde-4909-9bee-7e98be5214b9\",\"triggerValues\":[\"yes\"]}},{\"id\":\"1d5ea0f0-e259-40c2-99c5-a9197cf71c95\",\"text\":\"Une fiche de non-conformité a-t-elle été émise et transmise à la Direction des Achats ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true,\"dependsOn\":{\"questionId\":\"d0171833-dcde-4909-9bee-7e98be5214b9\",\"triggerValues\":[\"yes\"]}}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T09:37:46.390Z','2026-10-21T09:37:46.390Z','container');
